import React, { useState, useRef, useEffect, useLayoutEffect } from 'react';
import { FunctionCircuit, CircuitComponent, Wire, ComponentType } from '../types';
import { LogicCanvasHandle } from '../components/LogicCanvas';

const LOCAL_STORAGE_KEY = 'logicflow_autosave_v2';
const LOCAL_STORAGE_ID_KEY = 'logicflow_active_id_v2';

// Helper to create initial circuits
const createDefaultLibrary = (): FunctionCircuit[] => {
  const main: FunctionCircuit = { id: 'main', name: 'Main Circuit', components: [], wires: [] };

  // -- Half Adder --
  const ha_id = 'ha-001';
  const ha_comp_a: CircuitComponent = { id: 'ha-in-a', type: ComponentType.INPUT_SWITCH, x: 0, y: 0, inputValues: [], outputValues: [[]], bitWidth: 1, customLabel: "A" };
  const ha_comp_b: CircuitComponent = { id: 'ha-in-b', type: ComponentType.INPUT_SWITCH, x: 0, y: 120, inputValues: [], outputValues: [[]], bitWidth: 1, customLabel: "B" };
  const ha_comp_xor: CircuitComponent = { id: 'ha-xor', type: ComponentType.XOR, x: 200, y: 0, inputValues: [[],[]], outputValues: [[]], bitWidth: 1 };
  const ha_comp_and: CircuitComponent = { id: 'ha-and', type: ComponentType.AND, x: 200, y: 120, inputValues: [[],[]], outputValues: [[]], bitWidth: 1 };
  const ha_comp_sum: CircuitComponent = { id: 'ha-out-s', type: ComponentType.OUTPUT_LED, x: 400, y: 0, inputValues: [[]], outputValues: [], bitWidth: 1, customLabel: "S" };
  const ha_comp_carry: CircuitComponent = { id: 'ha-out-c', type: ComponentType.OUTPUT_LED, x: 400, y: 120, inputValues: [[]], outputValues: [], bitWidth: 1, customLabel: "C" };

  const ha_wires: Wire[] = [
      { id: 'w1', fromCompId: 'ha-in-a', fromPortIndex: 0, toCompId: 'ha-xor', toPortIndex: 0, state: [false], bitWidth: 1 },
      { id: 'w2', fromCompId: 'ha-in-b', fromPortIndex: 0, toCompId: 'ha-xor', toPortIndex: 1, state: [false], bitWidth: 1 },
      { id: 'w3', fromCompId: 'ha-in-a', fromPortIndex: 0, toCompId: 'ha-and', toPortIndex: 0, state: [false], bitWidth: 1 },
      { id: 'w4', fromCompId: 'ha-in-b', fromPortIndex: 0, toCompId: 'ha-and', toPortIndex: 1, state: [false], bitWidth: 1 },
      { id: 'w5', fromCompId: 'ha-xor', fromPortIndex: 0, toCompId: 'ha-out-s', toPortIndex: 0, state: [false], bitWidth: 1 },
      { id: 'w6', fromCompId: 'ha-and', fromPortIndex: 0, toCompId: 'ha-out-c', toPortIndex: 0, state: [false], bitWidth: 1 },
  ];
  const halfAdder: FunctionCircuit = { id: ha_id, name: 'Half Adder', components: [ha_comp_a, ha_comp_b, ha_comp_xor, ha_comp_and, ha_comp_sum, ha_comp_carry], wires: ha_wires };

  // -- 2:1 Mux --
  const mux_id = 'mux-001';
  const m_in_a: CircuitComponent = { id: 'm-a', type: ComponentType.INPUT_SWITCH, x: 0, y: 0, inputValues: [], outputValues: [[]], bitWidth: 1, customLabel: "A" };
  const m_in_b: CircuitComponent = { id: 'm-b', type: ComponentType.INPUT_SWITCH, x: 0, y: 80, inputValues: [], outputValues: [[]], bitWidth: 1, customLabel: "B" };
  const m_in_s: CircuitComponent = { id: 'm-s', type: ComponentType.INPUT_SWITCH, x: 0, y: 160, inputValues: [], outputValues: [[]], bitWidth: 1, customLabel: "Sel" };
  const m_not: CircuitComponent = { id: 'm-not', type: ComponentType.NOT, x: 120, y: 160, inputValues: [[]], outputValues: [[]], bitWidth: 1 };
  const m_and1: CircuitComponent = { id: 'm-and1', type: ComponentType.AND, x: 240, y: 20, inputValues: [[],[]], outputValues: [[]], bitWidth: 1 };
  const m_and2: CircuitComponent = { id: 'm-and2', type: ComponentType.AND, x: 240, y: 120, inputValues: [[],[]], outputValues: [[]], bitWidth: 1 };
  const m_or: CircuitComponent = { id: 'm-or', type: ComponentType.OR, x: 380, y: 70, inputValues: [[],[]], outputValues: [[]], bitWidth: 1 };
  const m_out: CircuitComponent = { id: 'm-out', type: ComponentType.OUTPUT_LED, x: 500, y: 70, inputValues: [[]], outputValues: [], bitWidth: 1, customLabel: "Y" };

  const mux_wires: Wire[] = [
      { id: 'mw1', fromCompId: 'm-s', fromPortIndex: 0, toCompId: 'm-not', toPortIndex: 0, state: [false], bitWidth: 1 },
      { id: 'mw2', fromCompId: 'm-a', fromPortIndex: 0, toCompId: 'm-and1', toPortIndex: 0, state: [false], bitWidth: 1 },
      { id: 'mw3', fromCompId: 'm-not', fromPortIndex: 0, toCompId: 'm-and1', toPortIndex: 1, state: [false], bitWidth: 1 },
      { id: 'mw4', fromCompId: 'm-b', fromPortIndex: 0, toCompId: 'm-and2', toPortIndex: 0, state: [false], bitWidth: 1 },
      { id: 'mw5', fromCompId: 'm-s', fromPortIndex: 0, toCompId: 'm-and2', toPortIndex: 1, state: [false], bitWidth: 1 },
      { id: 'mw6', fromCompId: 'm-and1', fromPortIndex: 0, toCompId: 'm-or', toPortIndex: 0, state: [false], bitWidth: 1 },
      { id: 'mw7', fromCompId: 'm-and2', fromPortIndex: 0, toCompId: 'm-or', toPortIndex: 1, state: [false], bitWidth: 1 },
      { id: 'mw8', fromCompId: 'm-or', fromPortIndex: 0, toCompId: 'm-out', toPortIndex: 0, state: [false], bitWidth: 1 },
  ];
  const mux21: FunctionCircuit = { id: mux_id, name: '2:1 Mux', components: [m_in_a, m_in_b, m_in_s, m_not, m_and1, m_and2, m_or, m_out], wires: mux_wires };

  return [main, halfAdder, mux21];
};

export const useProjectManager = (canvasRef: React.RefObject<LogicCanvasHandle | null>) => {
  const [functions, setFunctions] = useState<FunctionCircuit[]>(() => {
    try {
      const saved = localStorage.getItem(LOCAL_STORAGE_KEY);
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) return parsed;
      }
    } catch (e) { console.error(e); }
    return createDefaultLibrary();
  });

  const [activeFunctionId, setActiveFunctionId] = useState<string>(() => {
    try {
        const savedId = localStorage.getItem(LOCAL_STORAGE_ID_KEY);
        if (savedId) return savedId;
    } catch(e) {}
    return 'main';
  });

  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [dataVersion, setDataVersion] = useState(0);

  const functionsRef = useRef(functions);
  const activeIdRef = useRef(activeFunctionId);
  useEffect(() => { functionsRef.current = functions; }, [functions]);
  useEffect(() => { activeIdRef.current = activeFunctionId; }, [activeFunctionId]);

  useLayoutEffect(() => {
    if (!functions.find(f => f.id === activeFunctionId)) {
        setActiveFunctionId(functions[0]?.id || 'main');
    }
  }, [functions, activeFunctionId]);

  const getLatestFunctionsState = (): FunctionCircuit[] => {
    let currentData = functionsRef.current;
    if (canvasRef.current) {
        const { components, wires } = canvasRef.current.getData();
        currentData = currentData.map(f => 
            f.id === activeIdRef.current 
              ? { ...f, components: [...components], wires: [...wires] } 
              : f
        );
    }
    return currentData;
  };

  const persist = () => {
    const data = getLatestFunctionsState();
    try {
        localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(data));
        localStorage.setItem(LOCAL_STORAGE_ID_KEY, activeIdRef.current);
        setLastSaved(new Date());
    } catch (e) { console.error("Save failed", e); }
  };

  useEffect(() => {
    const interval = setInterval(persist, 5000);
    const handleVis = () => { if (document.hidden) persist(); };
    const handleUnload = () => { persist(); };

    document.addEventListener("visibilitychange", handleVis);
    window.addEventListener("beforeunload", handleUnload);

    return () => {
        clearInterval(interval);
        document.removeEventListener("visibilitychange", handleVis);
        window.removeEventListener("beforeunload", handleUnload);
        persist();
    };
  }, []);

  const syncCanvasToState = () => {
      const updated = getLatestFunctionsState();
      setFunctions(updated);
      return updated;
  };

  const switchToFunction = (id: string) => {
    if (id === activeFunctionId) return;
    syncCanvasToState();
    setActiveFunctionId(id);
  };

  const addFunction = (name: string) => {
    const current = syncCanvasToState();
    const newId = crypto.randomUUID();
    const newFunc: FunctionCircuit = { id: newId, name, components: [], wires: [] };
    const next = [...current, newFunc];
    setFunctions(next);
    setActiveFunctionId(newId);
    persist();
  };

  const deleteFunction = (id: string) => {
    if (id === 'main') return;
    const next = functions.filter(f => f.id !== id);
    setFunctions(next);
    if (activeFunctionId === id) setActiveFunctionId('main');
    persist();
  };

  const importData = (data: any, isFullProject: boolean) => {
      if (isFullProject) {
        setFunctions(data);
        setActiveFunctionId(data[0].id);
        setDataVersion(v => v + 1);
      } else {
        const current = getLatestFunctionsState();
        setFunctions([...current, data]);
      }
      persist();
  };

  const clearData = () => {
    localStorage.removeItem(LOCAL_STORAGE_KEY);
    localStorage.removeItem(LOCAL_STORAGE_ID_KEY);
    setFunctions(createDefaultLibrary());
    setActiveFunctionId('main');
    setDataVersion(v => v + 1);
  };

  return {
      functions,
      activeFunctionId,
      activeFunction: functions.find(f => f.id === activeFunctionId) || functions[0],
      lastSaved,
      dataVersion,
      getLatestFunctionsState,
      switchToFunction,
      addFunction,
      deleteFunction,
      importData,
      clearData,
      persist
  };
};

import p5Types from 'p5';
import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_GRID, COLOR_WIRE_ON, COLOR_WIRE_OFF, COLOR_BUS_ON, COLOR_BUS_OFF, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE } from '../constants';

type PortPoint = { x: number, y: number, side: 'top' | 'bottom' | 'left' | 'right' };

export const bitsToHex = (bits: boolean[]): string => {
  if (!bits || bits.length === 0) return "0";
  let val = 0n;
  for (let i = 0; i < bits.length; i++) {
      if (bits[i]) val |= (1n << BigInt(i));
  }
  return val.toString(16).toUpperCase();
};

export class CircuitRenderer {

  static getSide(c: CircuitComponent, isInput: boolean): PortSide {
    return c.icPortSide || (isInput ? 'left' : 'right');
  }

  static sortICPorts(components: CircuitComponent[], isInput: boolean) {
      const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };

      return [...components].sort((a, b) => {
          const sideA = CircuitRenderer.getSide(a, isInput);
          const sideB = CircuitRenderer.getSide(b, isInput);

          if (sideOrder[sideA] !== sideOrder[sideB]) {
              return sideOrder[sideA] - sideOrder[sideB];
          }
          if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
          return a.y - b.y;
      });
  }

  static getComponentDimensions(comp: CircuitComponent, library: FunctionCircuit[] = []) {
    const def = COMPONENT_DEFINITIONS[comp.type];

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
       const funcDef = library.find(f => f.id === comp.functionId);
       if (funcDef) {
          const inputs = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH);
          const outputs = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

          const countSide = (list: CircuitComponent[], side: PortSide, isInput: boolean) => 
              list.filter(c => CircuitRenderer.getSide(c, isInput) === side).length;

          const topCount = countSide(inputs, 'top', true) + countSide(outputs, 'top', false);
          const bottomCount = countSide(inputs, 'bottom', true) + countSide(outputs, 'bottom', false);
          const leftCount = countSide(inputs, 'left', true) + countSide(outputs, 'left', false);
          const rightCount = countSide(inputs, 'right', true) + countSide(outputs, 'right', false);

          const width = Math.max(2, topCount, bottomCount);
          const height = Math.max(2, leftCount, rightCount);

          return { w: width, h: height, inputs: inputs.length, outputs: outputs.length };
       }
       return { w: 1, h: 1, inputs: 0, outputs: 0 };
    }
    return { w: def.width, h: def.height, inputs: def.inputs, outputs: def.outputs };
  }

  static getPortPosition(comp: CircuitComponent, index: number, type: 'input' | 'output', library: FunctionCircuit[] = []): PortPoint {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;

    if (comp.type === ComponentType.INPUT_SWITCH && type === 'output') {
        const side = comp.icPortSide || 'right'; 
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }
    if (comp.type === ComponentType.OUTPUT_LED && type === 'input') {
        const side = comp.icPortSide || 'left';
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
         const funcDef = library.find(f => f.id === comp.functionId);
         if (funcDef) {
             const isInput = type === 'input';
             const unsorted = isInput 
                ? funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH)
                : funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

             const sorted = CircuitRenderer.sortICPorts(unsorted, isInput);
             const targetComp = sorted[index];

             if (targetComp) {
                 const side = CircuitRenderer.getSide(targetComp, isInput);
                 const inputsOnSide = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH && CircuitRenderer.getSide(c, true) === side);
                 const outputsOnSide = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED && CircuitRenderer.getSide(c, false) === side);
                 const allOnSide = [...inputsOnSide, ...outputsOnSide];
                 allOnSide.sort((a, b) => {
                    if (side === 'top' || side === 'bottom') return a.x - b.x;
                    return a.y - b.y;
                 });

                 const localIndex = allOnSide.indexOf(targetComp);
                 const count = allOnSide.length;
                 const stepX = w / (count + 1);
                 const stepY = h / (count + 1);

                 if (side === 'top') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y, side: 'top' };
                 if (side === 'bottom') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y + h, side: 'bottom' };
                 if (side === 'left') return { x: comp.x, y: comp.y + ((localIndex + 1) * stepY), side: 'left' };
                 if (side === 'right') return { x: comp.x + w, y: comp.y + ((localIndex + 1) * stepY), side: 'right' };
             }
         }
    }

    if (comp.type === ComponentType.SPLITTER) {
        if (type === 'input') return { x: comp.x, y: comp.y + h/2, side: 'left' };
        const step = h / 3;
        return { x: comp.x + w, y: comp.y + ((index+1)*step), side: 'right' };
    }
    if (comp.type === ComponentType.MERGER) {
        if (type === 'output') return { x: comp.x + w, y: comp.y + h/2, side: 'right' };
        const step = h / 3;
        return { x: comp.x, y: comp.y + ((index+1)*step), side: 'left' };
    }

    const count = type === 'input' ? dims.inputs : dims.outputs;
    const yStep = h / (count + 1);
    return {
      x: type === 'input' ? comp.x : comp.x + w,
      y: comp.y + ((index + 1) * yStep),
      side: type === 'input' ? 'left' : 'right'
    };
  }

  static getWireColor(width: number, hasSignal: boolean) {
      if (width === 1) return hasSignal ? COLOR_WIRE_ON : COLOR_WIRE_OFF;
      return hasSignal ? COLOR_BUS_ON : COLOR_BUS_OFF;
  }

  static getWireWeight(width: number) {
      if (width === 1) return 1.5;
      return Math.min(10, 2 + Math.ceil(Math.log2(width)));
  }

  static isSignalActive(state: boolean[]): boolean {
      if (!state) return false;
      return state.some(b => b === true);
  }

  static drawGrid(p: p5Types, viewport: { x: number, y: number, zoom: number }) {
    const visibleL = -viewport.x / viewport.zoom;
    const visibleT = -viewport.y / viewport.zoom;
    const visibleR = (p.width - viewport.x) / viewport.zoom;
    const visibleB = (p.height - viewport.y) / viewport.zoom;

    const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
    const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
    const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
    const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

    p.stroke(COLOR_GRID);
    p.strokeWeight(1 / viewport.zoom); 

    for (let x = startX; x <= endX; x += GRID_SIZE) p.line(x, visibleT, x, visibleB);
    for (let y = startY; y <= endY; y += GRID_SIZE) p.line(visibleL, y, visibleR, y);
  }

  static drawWire(p: p5Types, wire: Wire, components: CircuitComponent[], library: FunctionCircuit[], style: 'bezier' | 'orthogonal' = 'bezier') {
      const fromComp = components.find(c => c.id === wire.fromCompId);
      const toComp = components.find(c => c.id === wire.toCompId);
      if (fromComp && toComp) {
        const start = CircuitRenderer.getPortPosition(fromComp, wire.fromPortIndex, 'output', library);
        const end = CircuitRenderer.getPortPosition(toComp, wire.toPortIndex, 'input', library);
        const active = CircuitRenderer.isSignalActive(wire.state);
        const weight = CircuitRenderer.getWireWeight(wire.bitWidth);

        p.stroke(CircuitRenderer.getWireColor(wire.bitWidth, active));
        p.strokeWeight(weight);
        p.noFill();

        let midX = 0, midY = 0;
        if (style === 'orthogonal') {
            CircuitRenderer.drawOrthogonalWire(p, start, end);
            midX = (start.x + end.x) / 2;
            midY = start.y;
            if ((start.side === 'top' || start.side === 'bottom') && (end.side === 'top' || end.side === 'bottom')) {
                midY = (start.y + end.y) / 2;
                midX = start.x;
            }
        } else {
            const cpOffset = GRID_SIZE * 0.5;
            const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
            const cp2 = CircuitRenderer.getWireControlPoint(end, cpOffset);
            p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);
            midX = p.bezierPoint(start.x, cp1.x, cp2.x, end.x, 0.5);
            midY = p.bezierPoint(start.y, cp1.y, cp2.y, end.y, 0.5);
        }

        if (wire.bitWidth > 1) {
             const circleSize = Math.max(10, weight + 4);
             p.noStroke(); p.fill(COLOR_COMPONENT_BG); p.circle(midX, midY, circleSize);
             p.fill(COLOR_COMPONENT_STROKE); p.textAlign(p.CENTER, p.CENTER); p.textSize(7); p.text(wire.bitWidth, midX, midY);
        }
      }
  }

  static drawOrthogonalWire(p: p5Types, start: PortPoint, end: PortPoint) {
      let midX = (start.x + end.x) / 2;
      p.noFill(); p.beginShape(); p.vertex(start.x, start.y);
      const startVert = start.side === 'top' || start.side === 'bottom';
      const endVert = end.side === 'top' || end.side === 'bottom';
      if (startVert && endVert) {
          const midY = (start.y + end.y) / 2;
          p.vertex(start.x, midY); p.vertex(end.x, midY);
      } else if (startVert) {
          p.vertex(start.x, end.y);
      } else if (endVert) {
          p.vertex(end.x, start.y);
      } else {
          p.vertex(midX, start.y); p.vertex(midX, end.y);
      }
      p.vertex(end.x, end.y); p.endShape();
  }

  static drawDraftWire(p: p5Types, startInfo: { compId: string, portIndex: number, type: 'input'|'output', bitWidth: number }, mouseWorld: {x:number, y:number}, components: CircuitComponent[], library: FunctionCircuit[], style: 'bezier' | 'orthogonal' = 'bezier') {
      const comp = components.find(c => c.id === startInfo.compId);
      if (comp) {
        const start = CircuitRenderer.getPortPosition(comp, startInfo.portIndex, startInfo.type, library);
        p.stroke(COLOR_WIRE_OFF);
        p.strokeWeight(CircuitRenderer.getWireWeight(startInfo.bitWidth));
        p.noFill();
        if (style === 'orthogonal') {
             const targetSide = start.side === 'left' ? 'right' : (start.side === 'right' ? 'left' : (start.side === 'top' ? 'bottom' : 'top'));
             CircuitRenderer.drawOrthogonalWire(p, start, { x: mouseWorld.x, y: mouseWorld.y, side: targetSide });
        } else {
            const cpOffset = GRID_SIZE * 0.5;
            const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
            let cp2 = { x: mouseWorld.x, y: mouseWorld.y };
            if (startInfo.type === 'output') cp2 = { x: mouseWorld.x - cpOffset, y: mouseWorld.y };
            else cp2 = { x: mouseWorld.x + cpOffset, y: mouseWorld.y };
            p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, mouseWorld.x, mouseWorld.y);
        }
      }
  }

  static getWireControlPoint(pt: PortPoint, offset: number) {
    if (pt.side === 'top') return { x: pt.x, y: pt.y - offset };
    if (pt.side === 'bottom') return { x: pt.x, y: pt.y + offset };
    if (pt.side === 'left') return { x: pt.x - offset, y: pt.y };
    return { x: pt.x + offset, y: pt.y };
  }

  static drawComponent(p: p5Types, comp: CircuitComponent, library: FunctionCircuit[], isSelected: boolean) {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;
    p.push(); p.translate(comp.x, comp.y);
    if (comp.type === ComponentType.CUSTOM_IC) { CircuitRenderer.drawIC(p, comp, w, h, library); }
    else if (comp.type === ComponentType.SPLITTER) { CircuitRenderer.drawSplitter(p, comp, w, h); }
    else if (comp.type === ComponentType.MERGER) { CircuitRenderer.drawMerger(p, comp, w, h); }
    else if (comp.type === ComponentType.INPUT_SWITCH) { CircuitRenderer.drawSwitch(p, comp, w, h); }
    else if (comp.type === ComponentType.OUTPUT_LED) { CircuitRenderer.drawLED(p, comp, w, h); }
    else if (comp.type === ComponentType.HEX_DISPLAY) { CircuitRenderer.drawHex(p, comp, w, h); }
    else { CircuitRenderer.drawGate(p, comp, w, h); }
    if (comp.type !== ComponentType.CUSTOM_IC) { CircuitRenderer.drawLabels(p, comp, w, h); }
    if (isSelected) {
        p.noFill(); p.stroke('#3b82f6'); p.strokeWeight(1.5); p.rect(-3, -3, w + 6, h + 6, 4);
    }
    p.pop();
  }

  static drawSelectionRect(p: p5Types, x: number, y: number, w: number, h: number) {
      let rx = x, ry = y, rw = w, rh = h;
      if (rw < 0) { rx += rw; rw = Math.abs(rw); }
      if (rh < 0) { ry += rh; rh = Math.abs(rh); }
      p.noStroke(); p.fill(59, 130, 246, 20); p.rect(rx, ry, rw, rh);
      p.noFill(); p.stroke(59, 130, 246, 120); p.strokeWeight(1); p.rect(rx, ry, rw, rh);
  }

  private static drawFittedText(p: p5Types, text: string, x: number, y: number, maxW: number, maxH: number) {
      let fontSize = 11; const minFontSize = 7;
      p.textSize(fontSize); p.textAlign(p.CENTER, p.CENTER);
      let currentText = text; let w = p.textWidth(currentText);
      if (w <= maxW) { p.text(currentText, x, y); return; }
      while (fontSize > minFontSize && w > maxW) { fontSize--; p.textSize(fontSize); w = p.textWidth(currentText); }
      if (w > maxW) { while (currentText.length > 0 && p.textWidth(currentText + '..') > maxW) { currentText = currentText.slice(0, -1); } currentText += '..'; }
      p.text(currentText, x, y);
  }

  private static drawSplitter(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(1.5);
      p.beginShape(); p.vertex(0, h * 0.35); p.vertex(w, 0); p.vertex(w, h); p.vertex(0, h * 0.65); p.endShape(p.CLOSE);
      p.fill('#64748b'); p.noStroke(); p.circle(0, h/2, 4); 
      p.circle(w, h/4, 3); p.circle(w, 3*h/4, 3);
  }

  private static drawMerger(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(1.5);
      p.beginShape(); p.vertex(0, 0); p.vertex(w, h * 0.35); p.vertex(w, h * 0.65); p.vertex(0, h); p.endShape(p.CLOSE);
      p.fill('#64748b'); p.noStroke(); p.circle(0, h/4, 3); p.circle(0, 3*h/4, 3); p.circle(w, h/2, 4);
  }

  private static drawIC(p: p5Types, comp: CircuitComponent, w: number, h: number, library: FunctionCircuit[]) {
    p.fill('#f8fafc'); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(1.5); p.rect(0, 0, w, h, 4);
    p.fill('#334155'); p.noStroke(); p.textStyle(p.BOLD);
    CircuitRenderer.drawFittedText(p, comp.customLabel || "IC", w/2, h/2, w - 6, h - 6);
    p.textStyle(p.NORMAL);
  }

  private static drawSwitch(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.outputValues[0]);
      p.fill(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(1.5);
      p.rect(GRID_SIZE*0.1, GRID_SIZE*0.1, GRID_SIZE*0.8, GRID_SIZE*0.8, 3);
      p.fill(isOn ? '#fff' : '#475569'); p.noStroke(); p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
      p.text(isOn ? "1" : "0", w/2, h/2);
  }

  private static drawLED(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.inputValues[0]);
      p.fill(isOn ? COLOR_WIRE_ON : '#f1f5f9'); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(1.5);
      p.rect(GRID_SIZE*0.1, GRID_SIZE*0.1, GRID_SIZE*0.8, GRID_SIZE*0.8, 8);
  }

  private static drawHex(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      p.fill('#1e293b'); p.stroke(COLOR_COMPONENT_STROKE); p.rect(4, 4, w - 8, h - 8, 2);
      p.fill('#38bdf8'); p.noStroke(); p.textStyle(p.BOLD);
      const hex = bitsToHex(comp.inputValues[0] || []);
      CircuitRenderer.drawFittedText(p, hex, w/2, h/2, w - 12, h - 12);
      p.textStyle(p.NORMAL);
  }

  private static drawGate(p: p5Types, comp: CircuitComponent, w: number, h: number) {
    p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(1.5); p.fill(COLOR_COMPONENT_BG);
    const py = 8; const gw = w - 8; const isNegated = comp.type.startsWith('N') && comp.type !== 'NOT';
    if (comp.type === 'NOT') { p.triangle(0, py, 0, h - py, gw-4, h/2); p.circle(gw, h/2, 6); }
    else if (comp.type === 'AND' || comp.type === 'NAND') {
        p.beginShape(); p.vertex(0, py); p.vertex(gw/2, py); p.arc(gw/2, h/2, gw, h-2*py, -p.HALF_PI, p.HALF_PI); p.vertex(0, h-py); p.endShape(p.CLOSE);
        if (isNegated) p.circle(gw+3, h/2, 6);
    } else {
        p.rect(0, py, gw, h - 2*py, 2);
        p.noStroke(); p.fill(COLOR_COMPONENT_STROKE); p.textSize(8); p.textAlign(p.CENTER, p.CENTER);
        p.text(comp.type, gw/2, h/2);
    }
  }

  private static drawLabels(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      if (comp.customLabel) {
        p.noStroke(); p.fill('#64748b'); p.textSize(9); p.textAlign(p.CENTER, p.BOTTOM);
        p.text(comp.customLabel, w/2, -2);
      }
  }
}

import React, { useState } from 'react';
import { ComponentType, FunctionCircuit } from '../types';
import { COMPONENT_DEFINITIONS, VALID_BIT_WIDTHS } from '../constants';
import DraggableItem from './DraggableItem';

interface SidebarProps {
  selectedTool: 'CURSOR' | 'REGION' | 'DELETE';
  onSelectTool: (t: 'CURSOR' | 'REGION' | 'DELETE') => void;
  selectedBitWidth: number;
  onSelectBitWidth: (w: number) => void;
  onTouchStartItem?: (type: ComponentType, pos: {x: number, y: number}, functionId?: string) => void;
  functionLibrary: FunctionCircuit[];
  onCopy: () => void;
  onPaste: () => void;
  onSelectAll: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ 
    selectedTool, onSelectTool, selectedBitWidth, onSelectBitWidth,
    onTouchStartItem, functionLibrary, onCopy, onPaste, onSelectAll
}) => {
  const [searchTerm, setSearchTerm] = useState("");

  const groups = [
    { name: 'Components', items: [ComponentType.INPUT_SWITCH, ComponentType.OUTPUT_LED, ComponentType.HEX_DISPLAY] },
    { name: 'Gates', items: [ComponentType.NOT, ComponentType.AND, ComponentType.OR, ComponentType.XOR, ComponentType.BUFFER] },
    { name: 'Bus', items: [ComponentType.SPLITTER, ComponentType.MERGER] }
  ];

  const filteredGroups = groups.map(group => ({
    ...group,
    items: group.items.filter(type => {
        if (!searchTerm) return true;
        const def = COMPONENT_DEFINITIONS[type];
        return def.label.toLowerCase().includes(searchTerm.toLowerCase());
    })
  })).filter(g => g.items.length > 0);

  const filteredFunctions = functionLibrary.filter(f => 
      f.id !== 'main' && (searchTerm ? f.name.toLowerCase().includes(searchTerm.toLowerCase()) : true)
  );

  return (
    <div className="w-64 bg-white border-r border-slate-200 flex flex-col h-full z-10 select-none">
      <div className="p-5 border-b border-slate-100">
        <h1 className="text-lg font-bold text-slate-800 tracking-tight">LogicFlow</h1>
        <p className="text-[10px] text-slate-400 uppercase font-semibold mt-1 tracking-wider">Simulator</p>
      </div>

      <div className="p-3 border-b border-slate-50">
        <input 
            type="text" placeholder="Search..." value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="w-full px-3 py-1.5 text-xs bg-slate-50 border border-slate-200 rounded-md outline-none focus:border-blue-300 transition-all text-slate-700"
        />
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-6 scrollbar-thin">
        <section>
          <div className="grid grid-cols-3 gap-1 mb-4">
            {['CURSOR', 'REGION', 'DELETE'].map(t => (
                <button key={t} onClick={() => onSelectTool(t as any)} 
                    className={`p-2 rounded text-[10px] font-bold transition-all border ${selectedTool === t ? 'bg-slate-800 text-white border-slate-800 shadow-sm' : 'bg-white text-slate-500 border-slate-100 hover:bg-slate-50'}`}>
                    {t === 'CURSOR' ? 'MOVE' : t}
                </button>
            ))}
          </div>

          <div className="grid grid-cols-3 gap-1">
             {[['📋', onCopy], ['📝', onPaste], ['✅', onSelectAll]].map(([icon, fn], i) => (
                 <button key={i} onClick={fn as any} className="py-2 bg-white border border-slate-100 rounded hover:bg-slate-50 text-sm">{icon as any}</button>
             ))}
          </div>
        </section>

        <section>
            <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">Bus Width</h3>
            <div className="flex flex-wrap gap-1">
                {VALID_BIT_WIDTHS.map(w => (
                    <button key={w} onClick={() => onSelectBitWidth(w)}
                        className={`px-2 py-1 text-[10px] font-bold rounded border transition-all ${selectedBitWidth === w ? 'bg-blue-50 border-blue-200 text-blue-600' : 'bg-white border-slate-100 text-slate-400 hover:border-slate-200'}`}>
                        {w}
                    </button>
                ))}
            </div>
        </section>

        {filteredGroups.map(group => (
          <section key={group.name}>
            <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">{group.name}</h3>
            <div className="grid grid-cols-2 gap-2">
              {group.items.map(type => (
                 <DraggableItem key={type} type={type} label={COMPONENT_DEFINITIONS[type].label} subLabel="" disabled={false} bitWidth={selectedBitWidth} onTouchStartItem={onTouchStartItem} />
              ))}
            </div>
          </section>
        ))}

        {filteredFunctions.length > 0 && (
            <section>
                 <h3 className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-3">Functions</h3>
                 <div className="space-y-2">
                    {filteredFunctions.map(func => (
                        <DraggableItem key={func.id} type={ComponentType.CUSTOM_IC} label={func.name} subLabel="" disabled={false} bitWidth={selectedBitWidth} functionId={func.id} isCustom={true} onTouchStartItem={onTouchStartItem} />
                    ))}
                 </div>
            </section>
        )}
      </div>
    </div>
  );
};

export default Sidebar;

import React from 'react';
import { ComponentType } from '../types';

interface DraggableItemProps {
    type: ComponentType;
    label: string;
    subLabel: string;
    disabled: boolean;
    bitWidth: number;
    functionId?: string;
    isCustom?: boolean;
    onTouchStartItem?: (type: ComponentType, pos: {x: number, y: number}, functionId?: string) => void;
}

const DraggableItem: React.FC<DraggableItemProps> = ({ 
    type, label, disabled, bitWidth, functionId, isCustom, onTouchStartItem 
}) => {

    const handleDragStart = (e: React.DragEvent) => {
        if (disabled) return;
        e.dataTransfer.setData('application/react-logic-sim', JSON.stringify({ type, functionId, bitWidth }));
    };

    const handleTouchStart = (e: React.TouchEvent) => {
        if (disabled || !onTouchStartItem) return;
        const touch = e.touches[0];
        onTouchStartItem(type, { x: touch.clientX, y: touch.clientY }, functionId);
    };

    const baseClass = `flex items-center px-3 py-2 rounded border transition-all cursor-grab active:cursor-grabbing select-none text-xs font-medium
        ${disabled ? 'opacity-30 grayscale pointer-events-none' : 'bg-white border-slate-100 hover:border-slate-300 hover:shadow-sm'}`;

    if (isCustom) {
        return (
             <div draggable onDragStart={handleDragStart} onTouchStart={handleTouchStart} className={`${baseClass} bg-blue-50/30 border-blue-100`}>
                 <div className="w-5 h-5 mr-2 rounded bg-blue-100 text-blue-600 flex items-center justify-center text-[8px] font-bold">IC</div>
                 <span className="truncate">{label}</span>
            </div>
        );
    }

    return (
        <div draggable onDragStart={handleDragStart} onTouchStart={handleTouchStart} className={baseClass}>
            <span className="truncate">{label}</span>
        </div>
    );
};

export default DraggableItem;

import p5Types from 'p5';
import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_GRID, COLOR_WIRE_ON, COLOR_WIRE_OFF, COLOR_BUS_ON, COLOR_BUS_OFF, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE } from '../constants';

type PortPoint = { x: number, y: number, side: 'top' | 'bottom' | 'left' | 'right' };

export const bitsToHex = (bits: boolean[]): string => {
  if (!bits || bits.length === 0) return "0";
  let val = 0n;
  for (let i = 0; i < bits.length; i++) {
      if (bits[i]) val |= (1n << BigInt(i));
  }
  return val.toString(16).toUpperCase();
};

export class CircuitRenderer {

  static getSide(c: CircuitComponent, isInput: boolean): PortSide {
    return c.icPortSide || (isInput ? 'left' : 'right');
  }

  static sortICPorts(components: CircuitComponent[], isInput: boolean) {
      const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };

      return [...components].sort((a, b) => {
          const sideA = CircuitRenderer.getSide(a, isInput);
          const sideB = CircuitRenderer.getSide(b, isInput);

          if (sideOrder[sideA] !== sideOrder[sideB]) {
              return sideOrder[sideA] - sideOrder[sideB];
          }
          if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
          return a.y - b.y;
      });
  }

  static getComponentDimensions(comp: CircuitComponent, library: FunctionCircuit[] = []) {
    const def = COMPONENT_DEFINITIONS[comp.type];

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
       const funcDef = library.find(f => f.id === comp.functionId);
       if (funcDef) {
          const inputs = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH);
          const outputs = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

          const countSide = (list: CircuitComponent[], side: PortSide, isInput: boolean) => 
              list.filter(c => CircuitRenderer.getSide(c, isInput) === side).length;

          const topCount = countSide(inputs, 'top', true) + countSide(outputs, 'top', false);
          const bottomCount = countSide(inputs, 'bottom', true) + countSide(outputs, 'bottom', false);
          const leftCount = countSide(inputs, 'left', true) + countSide(outputs, 'left', false);
          const rightCount = countSide(inputs, 'right', true) + countSide(outputs, 'right', false);

          const width = Math.max(2, topCount, bottomCount);
          const height = Math.max(2, leftCount, rightCount);

          return { w: width, h: height, inputs: inputs.length, outputs: outputs.length };
       }
       return { w: 1, h: 1, inputs: 0, outputs: 0 };
    }
    return { w: def.width, h: def.height, inputs: def.inputs, outputs: def.outputs };
  }

  static getPortPosition(comp: CircuitComponent, index: number, type: 'input' | 'output', library: FunctionCircuit[] = []): PortPoint {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;

    if (comp.type === ComponentType.INPUT_SWITCH && type === 'output') {
        const side = comp.icPortSide || 'right'; 
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }
    if (comp.type === ComponentType.OUTPUT_LED && type === 'input') {
        const side = comp.icPortSide || 'left';
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
         const funcDef = library.find(f => f.id === comp.functionId);
         if (funcDef) {
             const isInput = type === 'input';
             const unsorted = isInput 
                ? funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH)
                : funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

             const sorted = CircuitRenderer.sortICPorts(unsorted, isInput);
             const targetComp = sorted[index];

             if (targetComp) {
                 const side = CircuitRenderer.getSide(targetComp, isInput);
                 const inputsOnSide = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH && CircuitRenderer.getSide(c, true) === side);
                 const outputsOnSide = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED && CircuitRenderer.getSide(c, false) === side);
                 const allOnSide = [...inputsOnSide, ...outputsOnSide];
                 allOnSide.sort((a, b) => {
                    if (side === 'top' || side === 'bottom') return a.x - b.x;
                    return a.y - b.y;
                 });

                 const localIndex = allOnSide.indexOf(targetComp);
                 const count = allOnSide.length;
                 const stepX = w / (count + 1);
                 const stepY = h / (count + 1);

                 if (side === 'top') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y, side: 'top' };
                 if (side === 'bottom') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y + h, side: 'bottom' };
                 if (side === 'left') return { x: comp.x, y: comp.y + ((localIndex + 1) * stepY), side: 'left' };
                 if (side === 'right') return { x: comp.x + w, y: comp.y + ((localIndex + 1) * stepY), side: 'right' };
             }
         }
    }

    if (comp.type === ComponentType.SPLITTER) {
        if (type === 'input') return { x: comp.x, y: comp.y + h/2, side: 'left' };
        const step = h / 3;
        return { x: comp.x + w, y: comp.y + ((index+1)*step), side: 'right' };
    }
    if (comp.type === ComponentType.MERGER) {
        if (type === 'output') return { x: comp.x + w, y: comp.y + h/2, side: 'right' };
        const step = h / 3;
        return { x: comp.x, y: comp.y + ((index+1)*step), side: 'left' };
    }

    const count = type === 'input' ? dims.inputs : dims.outputs;
    const yStep = h / (count + 1);
    return {
      x: type === 'input' ? comp.x : comp.x + w,
      y: comp.y + ((index + 1) * yStep),
      side: type === 'input' ? 'left' : 'right'
    };
  }

  static getWireColor(width: number, hasSignal: boolean) {
      if (width === 1) return hasSignal ? COLOR_WIRE_ON : COLOR_WIRE_OFF;
      return hasSignal ? COLOR_BUS_ON : COLOR_BUS_OFF;
  }

  static getWireWeight(width: number) {
      if (width === 1) return 1.5;
      return Math.min(10, 2 + Math.ceil(Math.log2(width)));
  }

  static isSignalActive(state: boolean[]): boolean {
      if (!state) return false;
      return state.some(b => b === true);
  }

  static drawGrid(p: p5Types, viewport: { x: number, y: number, zoom: number }) {
    const visibleL = -viewport.x / viewport.zoom;
    const visibleT = -viewport.y / viewport.zoom;
    const visibleR = (p.width - viewport.x) / viewport.zoom;
    const visibleB = (p.height - viewport.y) / viewport.zoom;

    const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
    const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
    const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
    const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

    p.stroke(COLOR_GRID);
    p.strokeWeight(1 / viewport.zoom); 

    for (let x = startX; x <= endX; x += GRID_SIZE) p.line(x, visibleT, x, visibleB);
    for (let y = startY; y <= endY; y += GRID_SIZE) p.line(visibleL, y, visibleR, y);
  }

  static drawWire(p: p5Types, wire: Wire, components: CircuitComponent[], library: FunctionCircuit[], style: 'bezier' | 'orthogonal' = 'bezier') {
      const fromComp = components.find(c => c.id === wire.fromCompId);
      const toComp = components.find(c => c.id === wire.toCompId);
      if (fromComp && toComp) {
        const start = CircuitRenderer.getPortPosition(fromComp, wire.fromPortIndex, 'output', library);
        const end = CircuitRenderer.getPortPosition(toComp, wire.toPortIndex, 'input', library);
        const active = CircuitRenderer.isSignalActive(wire.state);
        const weight = CircuitRenderer.getWireWeight(wire.bitWidth);

        p.stroke(CircuitRenderer.getWireColor(wire.bitWidth, active));
        p.strokeWeight(weight);
        p.noFill();

        let midX = 0, midY = 0;
        if (style === 'orthogonal') {
            CircuitRenderer.drawOrthogonalWire(p, start, end);
            midX = (start.x + end.x) / 2;
            midY = start.y;
            if ((start.side === 'top' || start.side === 'bottom') && (end.side === 'top' || end.side === 'bottom')) {
                midY = (start.y + end.y) / 2;
                midX = start.x;
            }
        } else {
            const cpOffset = GRID_SIZE * 0.5;
            const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
            const cp2 = CircuitRenderer.getWireControlPoint(end, cpOffset);
            p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);
            midX = p.bezierPoint(start.x, cp1.x, cp2.x, end.x, 0.5);
            midY = p.bezierPoint(start.y, cp1.y, cp2.y, end.y, 0.5);
        }

        if (wire.bitWidth > 1) {
             const circleSize = Math.max(10, weight + 4);
             p.noStroke(); p.fill(COLOR_COMPONENT_BG); p.circle(midX, midY, circleSize);
             p.fill(COLOR_COMPONENT_STROKE); p.textAlign(p.CENTER, p.CENTER); p.textSize(7); p.text(wire.bitWidth, midX, midY);
        }
      }
  }

  static drawOrthogonalWire(p: p5Types, start: PortPoint, end: PortPoint) {
      let midX = (start.x + end.x) / 2;
      p.noFill(); p.beginShape(); p.vertex(start.x, start.y);
      const startVert = start.side === 'top' || start.side === 'bottom';
      const endVert = end.side === 'top' || end.side === 'bottom';
      if (startVert && endVert) {
          const midY = (start.y + end.y) / 2;
          p.vertex(start.x, midY); p.vertex(end.x, midY);
      } else if (startVert) {
          p.vertex(start.x, end.y);
      } else if (endVert) {
          p.vertex(end.x, start.y);
      } else {
          p.vertex(midX, start.y); p.vertex(midX, end.y);
      }
      p.vertex(end.x, end.y); p.endShape();
  }

  static drawDraftWire(p: p5Types, startInfo: { compId: string, portIndex: number, type: 'input'|'output', bitWidth: number }, mouseWorld: {x:number, y:number}, components: CircuitComponent[], library: FunctionCircuit[], style: 'bezier' | 'orthogonal' = 'bezier') {
      const comp = components.find(c => c.id === startInfo.compId);
      if (comp) {
        const start = CircuitRenderer.getPortPosition(comp, startInfo.portIndex, startInfo.type, library);
        p.stroke(COLOR_WIRE_OFF);
        p.strokeWeight(CircuitRenderer.getWireWeight(startInfo.bitWidth));
        p.noFill();
        if (style === 'orthogonal') {
             const targetSide = start.side === 'left' ? 'right' : (start.side === 'right' ? 'left' : (start.side === 'top' ? 'bottom' : 'top'));
             CircuitRenderer.drawOrthogonalWire(p, start, { x: mouseWorld.x, y: mouseWorld.y, side: targetSide });
        } else {
            const cpOffset = GRID_SIZE * 0.5;
            const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
            let cp2 = { x: mouseWorld.x, y: mouseWorld.y };
            if (startInfo.type === 'output') cp2 = { x: mouseWorld.x - cpOffset, y: mouseWorld.y };
            else cp2 = { x: mouseWorld.x + cpOffset, y: mouseWorld.y };
            p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, mouseWorld.x, mouseWorld.y);
        }
      }
  }

  static getWireControlPoint(pt: PortPoint, offset: number) {
    if (pt.side === 'top') return { x: pt.x, y: pt.y - offset };
    if (pt.side === 'bottom') return { x: pt.x, y: pt.y + offset };
    if (pt.side === 'left') return { x: pt.x - offset, y: pt.y };
    return { x: pt.x + offset, y: pt.y };
  }

  static drawComponent(p: p5Types, comp: CircuitComponent, library: FunctionCircuit[], isSelected: boolean) {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;
    p.push(); p.translate(comp.x, comp.y);
    if (comp.type === ComponentType.CUSTOM_IC) { CircuitRenderer.drawIC(p, comp, w, h, library); }
    else if (comp.type === ComponentType.SPLITTER) { CircuitRenderer.drawSplitter(p, comp, w, h); }
    else if (comp.type === ComponentType.MERGER) { CircuitRenderer.drawMerger(p, comp, w, h); }
    else if (comp.type === ComponentType.INPUT_SWITCH) { CircuitRenderer.drawSwitch(p, comp, w, h); }
    else if (comp.type === ComponentType.OUTPUT_LED) { CircuitRenderer.drawLED(p, comp, w, h); }
    else if (comp.type === ComponentType.HEX_DISPLAY) { CircuitRenderer.drawHex(p, comp, w, h); }
    else { CircuitRenderer.drawGate(p, comp, w, h); }
    if (comp.type !== ComponentType.CUSTOM_IC) { CircuitRenderer.drawLabels(p, comp, w, h); }
    if (isSelected) {
        p.noFill(); p.stroke('#3b82f6'); p.strokeWeight(1.5); p.rect(-3, -3, w + 6, h + 6, 4);
    }
    p.pop();
  }

  static drawSelectionRect(p: p5Types, x: number, y: number, w: number, h: number) {
      let rx = x, ry = y, rw = w, rh = h;
      if (rw < 0) { rx += rw; rw = Math.abs(rw); }
      if (rh < 0) { ry += rh; rh = Math.abs(rh); }
      p.noStroke(); p.fill(59, 130, 246, 20); p.rect(rx, ry, rw, rh);
      p.noFill(); p.stroke(59, 130, 246, 120); p.strokeWeight(1); p.rect(rx, ry, rw, rh);
  }

  private static drawFittedText(p: p5Types, text: string, x: number, y: number, maxW: number, maxH: number) {
      let fontSize = 11; const minFontSize = 7;
      p.textSize(fontSize); p.textAlign(p.CENTER, p.CENTER);
      let currentText = text; let w = p.textWidth(currentText);
      if (w <= maxW) { p.text(currentText, x, y); return; }
      while (fontSize > minFontSize && w > maxW) { fontSize--; p.textSize(fontSize); w = p.textWidth(currentText); }
      if (w > maxW) { while (currentText.length > 0 && p.textWidth(currentText + '..') > maxW) { currentText = currentText.slice(0, -1); } currentText += '..'; }
      p.text(currentText, x, y);
  }

  private static drawSplitter(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(1.5);
      p.beginShape(); p.vertex(0, h * 0.35); p.vertex(w, 0); p.vertex(w, h); p.vertex(0, h * 0.65); p.endShape(p.CLOSE);
      p.fill('#64748b'); p.noStroke(); p.circle(0, h/2, 4); 
      p.circle(w, h/4, 3); p.circle(w, 3*h/4, 3);
  }

  private static drawMerger(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(1.5);
      p.beginShape(); p.vertex(0, 0); p.vertex(w, h * 0.35); p.vertex(w, h * 0.65); p.vertex(0, h); p.endShape(p.CLOSE);
      p.fill('#64748b'); p.noStroke(); p.circle(0, h/4, 3); p.circle(0, 3*h/4, 3); p.circle(w, h/2, 4);
  }

  private static drawIC(p: p5Types, comp: CircuitComponent, w: number, h: number, library: FunctionCircuit[]) {
    p.fill('#f8fafc'); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(1.5); p.rect(0, 0, w, h, 4);
    p.fill('#334155'); p.noStroke(); p.textStyle(p.BOLD);
    CircuitRenderer.drawFittedText(p, comp.customLabel || "IC", w/2, h/2, w - 6, h - 6);
    p.textStyle(p.NORMAL);
  }

  private static drawSwitch(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.outputValues[0]);
      p.fill(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(1.5);
      p.rect(GRID_SIZE*0.1, GRID_SIZE*0.1, GRID_SIZE*0.8, GRID_SIZE*0.8, 3);
      p.fill(isOn ? '#fff' : '#475569'); p.noStroke(); p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
      p.text(isOn ? "1" : "0", w/2, h/2);
  }

  private static drawLED(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.inputValues[0]);
      p.fill(isOn ? COLOR_WIRE_ON : '#f1f5f9'); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(1.5);
      p.rect(GRID_SIZE*0.1, GRID_SIZE*0.1, GRID_SIZE*0.8, GRID_SIZE*0.8, 8);
  }

  private static drawHex(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      p.fill('#1e293b'); p.stroke(COLOR_COMPONENT_STROKE); p.rect(4, 4, w - 8, h - 8, 2);
      p.fill('#38bdf8'); p.noStroke(); p.textStyle(p.BOLD);
      const hex = bitsToHex(comp.inputValues[0] || []);
      CircuitRenderer.drawFittedText(p, hex, w/2, h/2, w - 12, h - 12);
      p.textStyle(p.NORMAL);
  }

  private static drawGate(p: p5Types, comp: CircuitComponent, w: number, h: number) {
    p.stroke(COLOR_COMPONENT_STROKE); 
    p.strokeWeight(1.5); 
    p.fill(COLOR_COMPONENT_BG);

    const py = 10; 
    const gw = w - 10; 
    const gh = h - 2 * py;
    const isNegated = comp.type.startsWith('N') && comp.type !== 'NOT';
    const isXor = comp.type === 'XOR';

    if (comp.type === 'NOT') {
        p.beginShape();
        p.vertex(0, py);
        p.vertex(0, h - py);
        p.vertex(gw - 4, h/2);
        p.endShape(p.CLOSE);
        p.circle(gw, h/2, 6);
    } else if (comp.type === 'AND' || comp.type === 'NAND') {
        p.beginShape();
        p.vertex(0, py);
        p.vertex(gw/2, py);
        p.bezierVertex(gw, py, gw, h - py, gw/2, h - py);
        p.vertex(0, h - py);
        p.endShape(p.CLOSE);
        if (isNegated) p.circle(gw + 3, h/2, 6);
    } else if (comp.type === 'OR' || comp.type === 'NOR' || comp.type === 'XOR') {
        // Shared shape logic for OR family
        const drawOrPath = (offsetX = 0) => {
            p.beginShape();
            p.vertex(offsetX, py);
            p.bezierVertex(offsetX + 10, py + 5, offsetX + 10, h - py - 5, offsetX, h - py);
            p.bezierVertex(offsetX + gw * 0.6, h - py, gw, h/2 + 5, gw, h/2);
            p.bezierVertex(gw, h/2 - 5, offsetX + gw * 0.6, py, offsetX, py);
            p.endShape(p.CLOSE);
        };

        if (isXor) {
            // Background line for XOR
            p.noFill();
            p.beginShape();
            p.vertex(-4, py);
            p.bezierVertex(6, py + 5, 6, h - py - 5, -4, h - py);
            p.endShape();
            p.fill(COLOR_COMPONENT_BG);
        }

        drawOrPath(0);
        if (isNegated) p.circle(gw + 3, h/2, 6);
    } else if (comp.type === 'BUFFER') {
        p.beginShape();
        p.vertex(0, py);
        p.vertex(0, h - py);
        p.vertex(gw, h/2);
        p.endShape(p.CLOSE);
    } else {
        // Fallback for unknown gates
        p.rect(0, py, gw, h - 2*py, 2);
        p.noStroke(); p.fill(COLOR_COMPONENT_STROKE); p.textSize(8); p.textAlign(p.CENTER, p.CENTER);
        p.text(comp.type, gw/2, h/2);
    }
  }

  private static drawLabels(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      if (comp.customLabel) {
        p.noStroke(); p.fill('#64748b'); p.textSize(9); p.textAlign(p.CENTER, p.BOTTOM);
        p.text(comp.customLabel, w/2, -2);
      }
  }
}

import p5Types from 'p5';
import { CircuitComponent, Wire, ComponentType, FunctionCircuit, PortSide } from '../types';
import { COMPONENT_DEFINITIONS, GRID_SIZE, COLOR_GRID, COLOR_WIRE_ON, COLOR_WIRE_OFF, COLOR_BUS_ON, COLOR_BUS_OFF, COLOR_COMPONENT_BG, COLOR_COMPONENT_STROKE } from '../constants';

type PortPoint = { x: number, y: number, side: 'top' | 'bottom' | 'left' | 'right' };

export const bitsToHex = (bits: boolean[]): string => {
  if (!bits || bits.length === 0) return "0";
  let val = 0n;
  for (let i = 0; i < bits.length; i++) {
      if (bits[i]) val |= (1n << BigInt(i));
  }
  return val.toString(16).toUpperCase();
};

export class CircuitRenderer {

  static getSide(c: CircuitComponent, isInput: boolean): PortSide {
    return c.icPortSide || (isInput ? 'left' : 'right');
  }

  static sortICPorts(components: CircuitComponent[], isInput: boolean) {
      const sideOrder: Record<PortSide, number> = { top: 0, right: 1, bottom: 2, left: 3 };

      return [...components].sort((a, b) => {
          const sideA = CircuitRenderer.getSide(a, isInput);
          const sideB = CircuitRenderer.getSide(b, isInput);

          if (sideOrder[sideA] !== sideOrder[sideB]) {
              return sideOrder[sideA] - sideOrder[sideB];
          }
          if (sideA === 'top' || sideA === 'bottom') return a.x - b.x;
          return a.y - b.y;
      });
  }

  static getComponentDimensions(comp: CircuitComponent, library: FunctionCircuit[] = []) {
    const def = COMPONENT_DEFINITIONS[comp.type];

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
       const funcDef = library.find(f => f.id === comp.functionId);
       if (funcDef) {
          const inputs = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH);
          const outputs = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

          const countSide = (list: CircuitComponent[], side: PortSide, isInput: boolean) => 
              list.filter(c => CircuitRenderer.getSide(c, isInput) === side).length;

          const topCount = countSide(inputs, 'top', true) + countSide(outputs, 'top', false);
          const bottomCount = countSide(inputs, 'bottom', true) + countSide(outputs, 'bottom', false);
          const leftCount = countSide(inputs, 'left', true) + countSide(outputs, 'left', false);
          const rightCount = countSide(inputs, 'right', true) + countSide(outputs, 'right', false);

          const width = Math.max(2, topCount, bottomCount);
          const height = Math.max(2, leftCount, rightCount);

          return { w: width, h: height, inputs: inputs.length, outputs: outputs.length };
       }
       return { w: 1, h: 1, inputs: 0, outputs: 0 };
    }
    return { w: def.width, h: def.height, inputs: def.inputs, outputs: def.outputs };
  }

  static getPortPosition(comp: CircuitComponent, index: number, type: 'input' | 'output', library: FunctionCircuit[] = []): PortPoint {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;

    if (comp.type === ComponentType.INPUT_SWITCH && type === 'output') {
        const side = comp.icPortSide || 'right'; 
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }
    if (comp.type === ComponentType.OUTPUT_LED && type === 'input') {
        const side = comp.icPortSide || 'left';
        if (side === 'right') return { x: comp.x + w, y: comp.y + (h/2), side: 'right' };
        if (side === 'left') return { x: comp.x, y: comp.y + (h/2), side: 'left' };
        if (side === 'top') return { x: comp.x + (w/2), y: comp.y, side: 'top' };
        if (side === 'bottom') return { x: comp.x + (w/2), y: comp.y + h, side: 'bottom' };
    }

    if (comp.type === ComponentType.CUSTOM_IC && comp.functionId) {
         const funcDef = library.find(f => f.id === comp.functionId);
         if (funcDef) {
             const isInput = type === 'input';
             const unsorted = isInput 
                ? funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH)
                : funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED);

             const sorted = CircuitRenderer.sortICPorts(unsorted, isInput);
             const targetComp = sorted[index];

             if (targetComp) {
                 const side = CircuitRenderer.getSide(targetComp, isInput);
                 const inputsOnSide = funcDef.components.filter(c => c.type === ComponentType.INPUT_SWITCH && CircuitRenderer.getSide(c, true) === side);
                 const outputsOnSide = funcDef.components.filter(c => c.type === ComponentType.OUTPUT_LED && CircuitRenderer.getSide(c, false) === side);
                 const allOnSide = [...inputsOnSide, ...outputsOnSide];
                 allOnSide.sort((a, b) => {
                    if (side === 'top' || side === 'bottom') return a.x - b.x;
                    return a.y - b.y;
                 });

                 const localIndex = allOnSide.indexOf(targetComp);
                 const count = allOnSide.length;
                 const stepX = w / (count + 1);
                 const stepY = h / (count + 1);

                 if (side === 'top') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y, side: 'top' };
                 if (side === 'bottom') return { x: comp.x + ((localIndex + 1) * stepX), y: comp.y + h, side: 'bottom' };
                 if (side === 'left') return { x: comp.x, y: comp.y + ((localIndex + 1) * stepY), side: 'left' };
                 if (side === 'right') return { x: comp.x + w, y: comp.y + ((localIndex + 1) * stepY), side: 'right' };
             }
         }
    }

    if (comp.type === ComponentType.SPLITTER) {
        if (type === 'input') return { x: comp.x, y: comp.y + h/2, side: 'left' };
        const step = h / 3;
        return { x: comp.x + w, y: comp.y + ((index+1)*step), side: 'right' };
    }
    if (comp.type === ComponentType.MERGER) {
        if (type === 'output') return { x: comp.x + w, y: comp.y + h/2, side: 'right' };
        const step = h / 3;
        return { x: comp.x, y: comp.y + ((index+1)*step), side: 'left' };
    }

    const count = type === 'input' ? dims.inputs : dims.outputs;
    const yStep = h / (count + 1);
    return {
      x: type === 'input' ? comp.x : comp.x + w,
      y: comp.y + ((index + 1) * yStep),
      side: type === 'input' ? 'left' : 'right'
    };
  }

  static getWireColor(width: number, hasSignal: boolean) {
      if (width === 1) return hasSignal ? COLOR_WIRE_ON : COLOR_WIRE_OFF;
      return hasSignal ? COLOR_BUS_ON : COLOR_BUS_OFF;
  }

  static getWireWeight(width: number) {
      if (width === 1) return 1.5;
      return Math.min(10, 2 + Math.ceil(Math.log2(width)));
  }

  static isSignalActive(state: boolean[]): boolean {
      if (!state) return false;
      return state.some(b => b === true);
  }

  static drawGrid(p: p5Types, viewport: { x: number, y: number, zoom: number }) {
    const visibleL = -viewport.x / viewport.zoom;
    const visibleT = -viewport.y / viewport.zoom;
    const visibleR = (p.width - viewport.x) / viewport.zoom;
    const visibleB = (p.height - viewport.y) / viewport.zoom;

    const startX = Math.floor(visibleL / GRID_SIZE) * GRID_SIZE;
    const endX = Math.ceil(visibleR / GRID_SIZE) * GRID_SIZE;
    const startY = Math.floor(visibleT / GRID_SIZE) * GRID_SIZE;
    const endY = Math.ceil(visibleB / GRID_SIZE) * GRID_SIZE;

    p.stroke(COLOR_GRID);
    p.strokeWeight(1 / viewport.zoom); 

    for (let x = startX; x <= endX; x += GRID_SIZE) p.line(x, visibleT, x, visibleB);
    for (let y = startY; y <= endY; y += GRID_SIZE) p.line(visibleL, y, visibleR, y);
  }

  static drawWire(p: p5Types, wire: Wire, components: CircuitComponent[], library: FunctionCircuit[], style: 'bezier' | 'orthogonal' = 'bezier') {
      const fromComp = components.find(c => c.id === wire.fromCompId);
      const toComp = components.find(c => c.id === wire.toCompId);
      if (fromComp && toComp) {
        const start = CircuitRenderer.getPortPosition(fromComp, wire.fromPortIndex, 'output', library);
        const end = CircuitRenderer.getPortPosition(toComp, wire.toPortIndex, 'input', library);
        const active = CircuitRenderer.isSignalActive(wire.state);
        const weight = CircuitRenderer.getWireWeight(wire.bitWidth);

        p.stroke(CircuitRenderer.getWireColor(wire.bitWidth, active));
        p.strokeWeight(weight);
        p.noFill();

        let midX = 0, midY = 0;
        if (style === 'orthogonal') {
            CircuitRenderer.drawOrthogonalWire(p, start, end);
            midX = (start.x + end.x) / 2;
            midY = start.y;
            if ((start.side === 'top' || start.side === 'bottom') && (end.side === 'top' || end.side === 'bottom')) {
                midY = (start.y + end.y) / 2;
                midX = start.x;
            }
        } else {
            const cpOffset = GRID_SIZE * 0.5;
            const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
            const cp2 = CircuitRenderer.getWireControlPoint(end, cpOffset);
            p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, end.x, end.y);
            midX = p.bezierPoint(start.x, cp1.x, cp2.x, end.x, 0.5);
            midY = p.bezierPoint(start.y, cp1.y, cp2.y, end.y, 0.5);
        }

        if (wire.bitWidth > 1) {
             const circleSize = Math.max(10, weight + 4);
             p.noStroke(); p.fill(COLOR_COMPONENT_BG); p.circle(midX, midY, circleSize);
             p.fill(COLOR_COMPONENT_STROKE); p.textAlign(p.CENTER, p.CENTER); p.textSize(7); p.text(wire.bitWidth, midX, midY);
        }
      }
  }

  static drawOrthogonalWire(p: p5Types, start: PortPoint, end: PortPoint) {
      p.noFill(); p.beginShape(); p.vertex(start.x, start.y);
      const startVert = start.side === 'top' || start.side === 'bottom';
      const endVert = end.side === 'top' || end.side === 'bottom';
      if (startVert && endVert) {
          const midY = (start.y + end.y) / 2;
          p.vertex(start.x, midY); p.vertex(end.x, midY);
      } else if (startVert) {
          p.vertex(start.x, end.y);
      } else if (endVert) {
          p.vertex(end.x, start.y);
      } else {
          let midX = (start.x + end.x) / 2;
          p.vertex(midX, start.y); p.vertex(midX, end.y);
      }
      p.vertex(end.x, end.y); p.endShape();
  }

  static drawDraftWire(p: p5Types, startInfo: { compId: string, portIndex: number, type: 'input'|'output', bitWidth: number }, mouseWorld: {x:number, y:number}, components: CircuitComponent[], library: FunctionCircuit[], style: 'bezier' | 'orthogonal' = 'bezier') {
      const comp = components.find(c => c.id === startInfo.compId);
      if (comp) {
        const start = CircuitRenderer.getPortPosition(comp, startInfo.portIndex, startInfo.type, library);
        p.stroke(COLOR_WIRE_OFF);
        p.strokeWeight(CircuitRenderer.getWireWeight(startInfo.bitWidth));
        p.noFill();
        if (style === 'orthogonal') {
             const targetSide = start.side === 'left' ? 'right' : (start.side === 'right' ? 'left' : (start.side === 'top' ? 'bottom' : 'top'));
             CircuitRenderer.drawOrthogonalWire(p, start, { x: mouseWorld.x, y: mouseWorld.y, side: targetSide });
        } else {
            const cpOffset = GRID_SIZE * 0.5;
            const cp1 = CircuitRenderer.getWireControlPoint(start, cpOffset);
            let cp2 = { x: mouseWorld.x, y: mouseWorld.y };
            if (startInfo.type === 'output') cp2 = { x: mouseWorld.x - cpOffset, y: mouseWorld.y };
            else cp2 = { x: mouseWorld.x + cpOffset, y: mouseWorld.y };
            p.bezier(start.x, start.y, cp1.x, cp1.y, cp2.x, cp2.y, mouseWorld.x, mouseWorld.y);
        }
      }
  }

  static getWireControlPoint(pt: PortPoint, offset: number) {
    if (pt.side === 'top') return { x: pt.x, y: pt.y - offset };
    if (pt.side === 'bottom') return { x: pt.x, y: pt.y + offset };
    if (pt.side === 'left') return { x: pt.x - offset, y: pt.y };
    return { x: pt.x + offset, y: pt.y };
  }

  static drawComponent(p: p5Types, comp: CircuitComponent, library: FunctionCircuit[], isSelected: boolean) {
    const dims = CircuitRenderer.getComponentDimensions(comp, library);
    const w = dims.w * GRID_SIZE;
    const h = dims.h * GRID_SIZE;
    p.push(); p.translate(comp.x, comp.y);
    if (comp.type === ComponentType.CUSTOM_IC) { CircuitRenderer.drawIC(p, comp, w, h, library); }
    else if (comp.type === ComponentType.SPLITTER) { CircuitRenderer.drawSplitter(p, comp, w, h); }
    else if (comp.type === ComponentType.MERGER) { CircuitRenderer.drawMerger(p, comp, w, h); }
    else if (comp.type === ComponentType.INPUT_SWITCH) { CircuitRenderer.drawSwitch(p, comp, w, h); }
    else if (comp.type === ComponentType.OUTPUT_LED) { CircuitRenderer.drawLED(p, comp, w, h); }
    else if (comp.type === ComponentType.HEX_DISPLAY) { CircuitRenderer.drawHex(p, comp, w, h); }
    else { CircuitRenderer.drawGate(p, comp, w, h); }
    if (comp.type !== ComponentType.CUSTOM_IC) { CircuitRenderer.drawLabels(p, comp, w, h); }
    if (isSelected) {
        p.noFill(); p.stroke('#3b82f6'); p.strokeWeight(1.5); p.rect(-3, -3, w + 6, h + 6, 4);
    }
    p.pop();
  }

  static drawSelectionRect(p: p5Types, x: number, y: number, w: number, h: number) {
      let rx = x, ry = y, rw = w, rh = h;
      if (rw < 0) { rx += rw; rw = Math.abs(rw); }
      if (rh < 0) { ry += rh; ry = Math.abs(rh); }
      p.noStroke(); p.fill(59, 130, 246, 20); p.rect(rx, ry, rw, rh);
      p.noFill(); p.stroke(59, 130, 246, 120); p.strokeWeight(1); p.rect(rx, ry, rw, rh);
  }

  private static drawFittedText(p: p5Types, text: string, x: number, y: number, maxW: number, maxH: number) {
      let fontSize = 11; const minFontSize = 7;
      p.textSize(fontSize); p.textAlign(p.CENTER, p.CENTER);
      let currentText = text; let w = p.textWidth(currentText);
      if (w <= maxW) { p.text(currentText, x, y); return; }
      while (fontSize > minFontSize && w > maxW) { fontSize--; p.textSize(fontSize); w = p.textWidth(currentText); }
      if (w > maxW) { while (currentText.length > 0 && p.textWidth(currentText + '..') > maxW) { currentText = currentText.slice(0, -1); } currentText += '..'; }
      p.text(currentText, x, y);
  }

  private static drawSplitter(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(1.5);
      p.beginShape(); p.vertex(0, h * 0.35); p.vertex(w, 0); p.vertex(w, h); p.vertex(0, h * 0.65); p.endShape(p.CLOSE);
      p.fill('#64748b'); p.noStroke(); p.circle(0, h/2, 4); 
      p.circle(w, h/4, 3); p.circle(w, 3*h/4, 3);
  }

  private static drawMerger(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      p.fill(COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(1.5);
      p.beginShape(); p.vertex(0, 0); p.vertex(w, h * 0.35); p.vertex(w, h * 0.65); p.vertex(0, h); p.endShape(p.CLOSE);
      p.fill('#64748b'); p.noStroke(); p.circle(0, h/4, 3); p.circle(0, 3*h/4, 3); p.circle(w, h/2, 4);
  }

  private static drawIC(p: p5Types, comp: CircuitComponent, w: number, h: number, library: FunctionCircuit[]) {
    p.fill('#f8fafc'); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(1.5); p.rect(0, 0, w, h, 4);
    p.fill('#334155'); p.noStroke(); p.textStyle(p.BOLD);
    CircuitRenderer.drawFittedText(p, comp.customLabel || "IC", w/2, h/2, w - 6, h - 6);
    p.textStyle(p.NORMAL);
  }

  private static drawSwitch(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.outputValues[0]);
      p.fill(isOn ? COLOR_WIRE_ON : COLOR_COMPONENT_BG); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(1.5);
      p.rect(GRID_SIZE*0.1, GRID_SIZE*0.1, GRID_SIZE*0.8, GRID_SIZE*0.8, 3);
      p.fill(isOn ? '#fff' : '#475569'); p.noStroke(); p.textSize(10); p.textAlign(p.CENTER, p.CENTER);
      p.text(isOn ? "1" : "0", w/2, h/2);
  }

  private static drawLED(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      const isOn = CircuitRenderer.isSignalActive(comp.inputValues[0]);
      p.fill(isOn ? COLOR_WIRE_ON : '#f1f5f9'); p.stroke(COLOR_COMPONENT_STROKE); p.strokeWeight(1.5);
      p.rect(GRID_SIZE*0.1, GRID_SIZE*0.1, GRID_SIZE*0.8, GRID_SIZE*0.8, 8);
  }

  private static drawHex(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      p.fill('#1e293b'); p.stroke(COLOR_COMPONENT_STROKE); p.rect(4, 4, w - 8, h - 8, 2);
      p.fill('#38bdf8'); p.noStroke(); p.textStyle(p.BOLD);
      const hex = bitsToHex(comp.inputValues[0] || []);
      CircuitRenderer.drawFittedText(p, hex, w/2, h/2, w - 12, h - 12);
      p.textStyle(p.NORMAL);
  }

  private static drawGate(p: p5Types, comp: CircuitComponent, w: number, h: number) {
    p.stroke(COLOR_COMPONENT_STROKE); 
    p.strokeWeight(1.5); 
    p.fill(COLOR_COMPONENT_BG);

    const isNegated = comp.type.startsWith('N') && comp.type !== 'NOT';
    const hasBubble = isNegated || comp.type === 'NOT';
    const bubbleSize = 6;

    // Exact port locations from getPortPosition logic
    const in1Y = h * 1/3;
    const in2Y = h * 2/3;
    const midY = h * 1/2;
    const outX = w;

    // Body dimensions to leave space for bubble and leads
    const margin = 5;
    const gateLeft = margin;
    const gateRight = hasBubble ? w - margin - bubbleSize : w - margin;
    const gateTop = margin;
    const gateBottom = h - margin;
    const gateWidth = gateRight - gateLeft;

    // Draw Input Leads
    p.noFill();
    if (comp.type !== 'INPUT' && comp.type !== 'OUTPUT' && comp.type !== 'IC') {
        const def = COMPONENT_DEFINITIONS[comp.type];
        if (def.inputs === 1) {
            p.line(0, midY, gateLeft, midY);
        } else if (def.inputs === 2) {
            p.line(0, in1Y, gateLeft, in1Y);
            p.line(0, in2Y, gateLeft, in2Y);
        }
    }

    p.fill(COLOR_COMPONENT_BG);
    if (comp.type === 'NOT') {
        p.beginShape();
        p.vertex(gateLeft, gateTop);
        p.vertex(gateLeft, gateBottom);
        p.vertex(gateRight, midY);
        p.endShape(p.CLOSE);
    } else if (comp.type === 'AND' || comp.type === 'NAND') {
        p.beginShape();
        p.vertex(gateLeft, gateTop);
        p.vertex(gateLeft + gateWidth/2, gateTop);
        p.bezierVertex(gateRight, gateTop, gateRight, gateBottom, gateLeft + gateWidth/2, gateBottom);
        p.vertex(gateLeft, gateBottom);
        p.endShape(p.CLOSE);
    } else if (comp.type === 'OR' || comp.type === 'NOR' || comp.type === 'XOR') {
        const drawOrShape = (xOffset = 0) => {
            p.beginShape();
            p.vertex(gateLeft + xOffset, gateTop);
            p.bezierVertex(gateLeft + 8 + xOffset, gateTop + 5, gateLeft + 8 + xOffset, gateBottom - 5, gateLeft + xOffset, gateBottom);
            p.bezierVertex(gateLeft + gateWidth * 0.6 + xOffset, gateBottom, gateRight + xOffset, midY + 5, gateRight + xOffset, midY);
            p.bezierVertex(gateRight + xOffset, midY - 5, gateLeft + gateWidth * 0.6 + xOffset, gateTop, gateLeft + xOffset, gateTop);
            p.endShape(p.CLOSE);
        };

        if (comp.type === 'XOR') {
            p.noFill();
            p.beginShape();
            p.vertex(gateLeft - 4, gateTop);
            p.bezierVertex(gateLeft + 4, gateTop + 5, gateLeft + 4, gateBottom - 5, gateLeft - 4, gateBottom);
            p.endShape();
            p.fill(COLOR_COMPONENT_BG);
        }
        drawOrShape(0);
    } else if (comp.type === 'BUFFER') {
        p.beginShape();
        p.vertex(gateLeft, gateTop);
        p.vertex(gateLeft, gateBottom);
        p.vertex(gateRight, midY);
        p.endShape(p.CLOSE);
    } else {
        p.rect(gateLeft, gateTop, gateWidth, gateBottom - gateTop, 2);
        p.noStroke(); p.fill(COLOR_COMPONENT_STROKE); p.textSize(8); p.textAlign(p.CENTER, p.CENTER);
        p.text(comp.type, gateLeft + gateWidth/2, midY);
        p.stroke(COLOR_COMPONENT_STROKE); p.fill(COLOR_COMPONENT_BG);
    }

    // Draw Inversion Bubble (Pochi)
    if (hasBubble) {
        p.circle(gateRight + bubbleSize/2, midY, bubbleSize);
        p.line(gateRight + bubbleSize, midY, outX, midY);
    } else {
        // Output lead
        p.line(gateRight, midY, outX, midY);
    }
  }

  private static drawLabels(p: p5Types, comp: CircuitComponent, w: number, h: number) {
      if (comp.customLabel) {
        p.noStroke(); p.fill('#64748b'); p.textSize(9); p.textAlign(p.CENTER, p.BOTTOM);
        p.text(comp.customLabel, w/2, -2);
      }
  }
}
